1	package com.tainted.authuser.social;
2	
3	import com.tainted.authuser.error.InvalidTokenException;
4	import org.springframework.stereotype.Component;
5	import java.util.Set;
6	
7	/**
8	 * 결정론적 소셜 검증 mock. 외부 호출 없음.
9	 * 유효 토큰 형식: "valid-<provider>-<seed>"  →  externalId = "<provider>:<seed>".
10	 */
11	@Component
12	public class MockSocialVerifier implements SocialVerifier {
13	
14	    private static final Set<String> SUPPORTED = Set.of("google", "kakao", "naver", "toss");
15	
16	    @Override
