        given().contentType(ContentType.JSON)
                .body("{\"provider\":\"google\",\"providerToken\":\"valid-google-u1\"}")
                .when().post("/api/v1/auth/login")
                .then().statusCode(200)
                .body("accessToken", not(emptyOrNullString()));
    }
}

