package com.tainted.authuser.blackbox;

import io.lettuce.core.RedisClient;
import io.lettuce.core.api.StatefulRedisConnection;
import io.lettuce.core.api.sync.RedisCommands;
import io.restassured.response.Response;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.time.Instant;
import java.util.Map;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.matchesPattern;
import static org.junit.jupiter.api.Assertions.*;

/**
 * Black-Box API Integration Test
 *
 * @target-controller AuthController (src/main/java/com/tainted/authuser/web/AuthController.java)
 * @target-api POST /api/v1/auth/guest
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class AuthGuestBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8081");

    private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:3306/authuser");
    private static final String DB_USER = System.getProperty("test.db.user", "root");
    private static final String DB_PASSWORD = System.getProperty("test.db.password", "rootpw");

    private static final String REDIS_HOST = System.getProperty("test.redis.host", "localhost");
    private static final int REDIS_PORT = Integer.getInteger("test.redis.port", 6379);

    private static final String REDIS_TOKEN_PREFIX = "auth:token:";
    private static final String UUID_PATTERN =
            "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$";

    private static RedisClient redisClient;

    @BeforeAll
    static void startClients() {
        redisClient = RedisClient.create("redis://" + REDIS_HOST + ":" + REDIS_PORT);
    }

    @AfterAll
    static void stopClients() {
        redisClient.shutdown();
    }

    // 병렬 안전: 각 SQL 실행마다 독립 Connection을 사용
    private static Connection getDbConnection() throws Exception {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
        try (Connection conn = getDbConnection();
             InputStream is = AuthGuestBlackBoxTest.class
                     .getClassLoader().getResourceAsStream(resourcePath);
             Statement stmt = conn.createStatement()) {
            String sql = new String(is.readAllBytes(), StandardCharsets.UTF_8);
            for (var entry : params.entrySet()) {
                sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
            }
            for (String line : sql.split("\n")) {
                String trimmed = line.trim();
                if (trimmed.startsWith("--") || trimmed.isEmpty()) continue;
                if (trimmed.endsWith(";")) trimmed = trimmed.substring(0, trimmed.length() - 1);
                if (!trimmed.isEmpty()) stmt.execute(trimmed);
            }
        } catch (Exception e) {
            throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
        }
    }

    private static String resolveUserId(RedisCommands<String, String> commands, String accessToken) {
        return commands.get(REDIS_TOKEN_PREFIX + accessToken);
    }

    @Test
    void NTC_guest_success_returnsTokenAndPersistsUser() {
        Response resp = given().log().all()
                .baseUri(BASE_URL)
                .when()
                .post("/api/v1/auth/guest")
                .then().log().all()
                .statusCode(200)
                .body("displayName", equalTo("익명"))
                .body("accessToken", matchesPattern(UUID_PATTERN))
                .extract().response();

        String accessToken = resp.path("accessToken");
        String userId;

        try (StatefulRedisConnection<String, String> conn = redisClient.connect()) {
            RedisCommands<String, String> commands = conn.sync();
            userId = resolveUserId(commands, accessToken);
            assertNotNull(userId, "token must resolve to a userId in Redis");
            assertTrue(userId.matches(UUID_PATTERN));

            long ttl = commands.ttl(REDIS_TOKEN_PREFIX + accessToken);
            assertTrue(ttl > 0 && ttl <= 3600, "TTL must be within (0, 3600], was " + ttl);
        }

        try {
            try (Connection dbConn = getDbConnection();
                 PreparedStatement ps = dbConn.prepareStatement(
                         "SELECT social_provider, external_id, created_at FROM user_account WHERE id = ?")) {
                ps.setString(1, userId);
                try (ResultSet rs = ps.executeQuery()) {
                    assertTrue(rs.next(), "guest user row must exist");
                    assertEquals("guest", rs.getString("social_provider"));
                    assertTrue(rs.getString("external_id").matches("^guest:[0-9a-fA-F-]{36}$"));
                    Instant createdAt = rs.getTimestamp("created_at").toInstant();
                    assertTrue(createdAt.isAfter(Instant.now().minusSeconds(120)));
                    assertTrue(createdAt.isBefore(Instant.now().plusSeconds(10)));
                }
            }
        } catch (Exception e) {
            throw new RuntimeException(e);
        } finally {
            executeSqlTemplate("sql/auth-guest-teardown.sql", Map.of("USER_ID", userId));
        }
    }

    @Test
    void NTC_guest_distinctUsersAcrossCalls() {
        String token1 = given().baseUri(BASE_URL).when().post("/api/v1/auth/guest")
                .then().statusCode(200).extract().path("accessToken");
        String token2 = given().baseUri(BASE_URL).when().post("/api/v1/auth/guest")
                .then().statusCode(200).extract().path("accessToken");

        assertNotEquals(token1, token2);

        String userId1, userId2;
        try (StatefulRedisConnection<String, String> conn = redisClient.connect()) {
            RedisCommands<String, String> commands = conn.sync();
            userId1 = resolveUserId(commands, token1);
            userId2 = resolveUserId(commands, token2);
        }
        assertNotNull(userId1);
        assertNotNull(userId2);
        assertNotEquals(userId1, userId2);

        try {
            try (Connection dbConn = getDbConnection();
                 PreparedStatement ps = dbConn.prepareStatement(
                         "SELECT COUNT(*) FROM user_account WHERE id IN (?, ?) AND social_provider = 'guest'")) {
                ps.setString(1, userId1);
                ps.setString(2, userId2);
                try (ResultSet rs = ps.executeQuery()) {
                    assertTrue(rs.next());
                    assertEquals(2, rs.getInt(1));
                }
            }
        } catch (Exception e) {
            throw new RuntimeException(e);
        } finally {
            executeSqlTemplate("sql/auth-guest-teardown.sql", Map.of("USER_ID", userId1));
            executeSqlTemplate("sql/auth-guest-teardown.sql", Map.of("USER_ID", userId2));
        }
    }

    @Test
    void NTC_guest_threeSequentialCallsEachPersistIndependently() {
        String[] tokens = new String[3];
        for (int i = 0; i < 3; i++) {
            tokens[i] = given().baseUri(BASE_URL).when().post("/api/v1/auth/guest")
                    .then().statusCode(200)
                    .body("displayName", equalTo("익명"))
                    .extract().path("accessToken");
        }

        String[] userIds = new String[3];
        try (StatefulRedisConnection<String, String> conn = redisClient.connect()) {
            RedisCommands<String, String> commands = conn.sync();
            for (int i = 0; i < 3; i++) {
                userIds[i] = resolveUserId(commands, tokens[i]);
                assertNotNull(userIds[i]);
            }
        }

        try {
            try (Connection dbConn = getDbConnection();
                 PreparedStatement ps = dbConn.prepareStatement(
                         "SELECT COUNT(*) FROM user_account WHERE id IN (?, ?, ?)")) {
                ps.setString(1, userIds[0]);
                ps.setString(2, userIds[1]);
                ps.setString(3, userIds[2]);
                try (ResultSet rs = ps.executeQuery()) {
                    assertTrue(rs.next());
                    assertEquals(3, rs.getInt(1));
                }
            }
        } catch (Exception e) {
            throw new RuntimeException(e);
        } finally {
            for (String userId : userIds) {
                executeSqlTemplate("sql/auth-guest-teardown.sql", Map.of("USER_ID", userId));
            }
        }
    }

    @Test
    void ATC_guest_wrongMethodReturns405() {
        // guest 는 요청 파라미터가 없어 VTC 표준 rule(RED 파라미터 대상)이 적용되지 않는다.
        // API 레벨 변조(wrongMethod)만 실행 가능한 유일한 변조 케이스.
        given().baseUri(BASE_URL).log().all()
                .when().get("/api/v1/auth/guest")
                .then().log().all()
                .statusCode(405);
    }
}

