package com.tainted.authuser.blackbox;

import io.lettuce.core.RedisClient;
import io.lettuce.core.api.StatefulRedisConnection;
import io.lettuce.core.api.sync.RedisCommands;
import io.restassured.http.ContentType;
import io.restassured.response.Response;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.Map;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.*;
import static org.junit.jupiter.api.Assertions.*;

/**
 * Black-Box API Integration Test
 *
 * @target-controller AuthController (src/main/java/com/tainted/authuser/web/AuthController.java)
 * @target-api POST /api/v1/auth/login
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class AuthLoginBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8081");

    private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:3306/authuser");
    private static final String DB_USER = System.getProperty("test.db.user", "root");
    private static final String DB_PASSWORD = System.getProperty("test.db.password", "rootpw");

    private static final String REDIS_HOST = System.getProperty("test.redis.host", "localhost");
    private static final int REDIS_PORT = Integer.getInteger("test.redis.port", 6379);

    private static final String REDIS_TOKEN_PREFIX = "auth:token:";
    private static final String UUID_PATTERN =
            "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$";

    private static RedisClient redisClient;

    @BeforeAll
    static void startClients() {
        redisClient = RedisClient.create("redis://" + REDIS_HOST + ":" + REDIS_PORT);
    }

    @AfterAll
    static void stopClients() {
        redisClient.shutdown();
    }

    // 병렬 안전: 각 SQL 실행마다 독립 Connection을 사용
    private static Connection getDbConnection() throws Exception {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
        try (Connection conn = getDbConnection();
             InputStream is = AuthLoginBlackBoxTest.class
                     .getClassLoader().getResourceAsStream(resourcePath);
             Statement stmt = conn.createStatement()) {
            String sql = new String(is.readAllBytes(), StandardCharsets.UTF_8);
            for (var entry : params.entrySet()) {
                sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
            }
            for (String line : sql.split("\n")) {
                String trimmed = line.trim();
                if (trimmed.startsWith("--") || trimmed.isEmpty()) continue;
                if (trimmed.endsWith(";")) trimmed = trimmed.substring(0, trimmed.length() - 1);
                if (!trimmed.isEmpty()) stmt.execute(trimmed);
            }
        } catch (Exception e) {
            throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
        }
    }

    // 메서드별 고유 ID/seed 생성 (결정적 — 메서드명 기반)
    private String testId(TestInfo info) {
        return String.format("T%09d",
                Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000);
    }

    private void teardownByExternalId(String provider, String externalId) {
        executeSqlTemplate("sql/auth-login-teardown.sql",
                Map.of("SOCIAL_PROVIDER", provider, "EXTERNAL_ID", externalId));
    }

    private String loginBody(String provider, String providerToken) {
        return "{\"provider\":\"" + provider + "\",\"providerToken\":\"" + providerToken + "\"}";
    }

    // ------------------------------------------------------------------
    // NTC — Happy Path
    // ------------------------------------------------------------------

    @Test
    void NTC_login_newUser_createsAccountAndIssuesToken(TestInfo info) {
        String seed = testId(info);
        String provider = "kakao";
        String externalId = provider + ":" + seed;

        teardownByExternalId(provider, externalId); // defensive pre-cleanup

        try {
            Response resp = given().log().all()
                    .baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body(loginBody(provider, "valid-" + provider + "-" + seed))
                    .when()
                    .post("/api/v1/auth/login")
                    .then().log().all()
                    .statusCode(200)
                    .body("displayName", equalTo("익명"))
                    .body("accessToken", matchesPattern(UUID_PATTERN))
                    .extract().response();

            String accessToken = resp.path("accessToken");

            try (Connection dbConn = getDbConnection();
                 PreparedStatement ps = dbConn.prepareStatement(
                         "SELECT id, social_provider FROM user_account WHERE external_id = ?")) {
                ps.setString(1, externalId);
                try (ResultSet rs = ps.executeQuery()) {
                    assertTrue(rs.next(), "new user_account row must be created");
                    assertEquals(provider, rs.getString("social_provider"));
                    String userId = rs.getString("id");

                    try (StatefulRedisConnection<String, String> conn = redisClient.connect()) {
                        RedisCommands<String, String> commands = conn.sync();
                        assertEquals(userId, commands.get(REDIS_TOKEN_PREFIX + accessToken));
                        long ttl = commands.ttl(REDIS_TOKEN_PREFIX + accessToken);
                        assertTrue(ttl > 0 && ttl <= 3600);
                    }
                }
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        } finally {
            teardownByExternalId(provider, externalId);
        }
    }

    @Test
    void NTC_login_existingUser_reusesAccountAndIssuesNewToken(TestInfo info) {
        String seed = testId(info);
        String provider = "kakao";
        String externalId = provider + ":" + seed;
        String preexistingId = "T" + seed;

        executeSqlTemplate("sql/auth-login-setup.sql", Map.of(
                "USER_ID", preexistingId, "SOCIAL_PROVIDER", provider, "EXTERNAL_ID", externalId));

        try {
            Response resp = given().log().all()
                    .baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body(loginBody(provider, "valid-" + provider + "-" + seed))
                    .when()
                    .post("/api/v1/auth/login")
                    .then().log().all()
                    .statusCode(200)
                    .body("accessToken", matchesPattern(UUID_PATTERN))
                    .extract().response();

            String accessToken = resp.path("accessToken");

            try (Connection dbConn = getDbConnection();
                 PreparedStatement ps = dbConn.prepareStatement(
                         "SELECT COUNT(*) AS cnt FROM user_account WHERE external_id = ?")) {
                ps.setString(1, externalId);
                try (ResultSet rs = ps.executeQuery()) {
                    assertTrue(rs.next());
                    assertEquals(1, rs.getInt("cnt"), "login for existing identity must not insert a second row");
                }
            } catch (Exception e) {
                throw new RuntimeException(e);
            }

            try (StatefulRedisConnection<String, String> conn = redisClient.connect()) {
                RedisCommands<String, String> commands = conn.sync();
                assertEquals(preexistingId, commands.get(REDIS_TOKEN_PREFIX + accessToken),
                        "issued token must resolve to the pre-existing user id, not a new one");
            }
        } finally {
            teardownByExternalId(provider, externalId);
        }
    }

    @Test
    void NTC_login_differentProvidersAreIndependent(TestInfo info) {
        String seed = testId(info);
        String kakaoExternalId = "kakao:" + seed;
        String naverExternalId = "naver:" + seed;

        teardownByExternalId("kakao", kakaoExternalId);
        teardownByExternalId("naver", naverExternalId);

        try {
            String kakaoToken = given().baseUri(BASE_URL).contentType(ContentType.JSON)
                    .body(loginBody("kakao", "valid-kakao-" + seed))
                    .when().post("/api/v1/auth/login")
                    .then().statusCode(200).extract().path("accessToken");

            String naverToken = given().baseUri(BASE_URL).contentType(ContentType.JSON)
                    .body(loginBody("naver", "valid-naver-" + seed))
                    .when().post("/api/v1/auth/login")
                    .then().statusCode(200).extract().path("accessToken");

            assertNotEquals(kakaoToken, naverToken);

            try (Connection dbConn = getDbConnection();
                 PreparedStatement ps = dbConn.prepareStatement(
                         "SELECT COUNT(*) AS cnt FROM user_account WHERE external_id IN (?, ?)")) {
                ps.setString(1, kakaoExternalId);
                ps.setString(2, naverExternalId);
                try (ResultSet rs = ps.executeQuery()) {
                    assertTrue(rs.next());
                    assertEquals(2, rs.getInt("cnt"), "same seed under different providers must create two rows");
                }
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        } finally {
            teardownByExternalId("kakao", kakaoExternalId);
            teardownByExternalId("naver", naverExternalId);
        }
    }

    @Test
    void NTC_login_tossProvider_alwaysUsesMockRegardlessOfMode(TestInfo info) {
        String seed = testId(info);
        String externalId = "toss:" + seed;

        teardownByExternalId("toss", externalId);

        try {
            given().log().all()
                    .baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body(loginBody("toss", "valid-toss-" + seed))
                    .when()
                    .post("/api/v1/auth/login")
                    .then().log().all()
                    .statusCode(200)
                    .body("accessToken", matchesPattern(UUID_PATTERN));

            try (Connection dbConn = getDbConnection();
                 PreparedStatement ps = dbConn.prepareStatement(
                         "SELECT social_provider FROM user_account WHERE external_id = ?")) {
                ps.setString(1, externalId);
                try (ResultSet rs = ps.executeQuery()) {
                    assertTrue(rs.next());
                    assertEquals("toss", rs.getString("social_provider"));
                }
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        } finally {
            teardownByExternalId("toss", externalId);
        }
    }

    // ------------------------------------------------------------------
    // ATC — Business Exceptions (401 via SocialVerifier InvalidTokenException)
    // ------------------------------------------------------------------

    @Test
    void ATC_login_unsupportedProvider_returns401ProblemJson() {
        given().log().all()
                .baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body(loginBody("facebook", "valid-facebook-u1"))
                .when()
                .post("/api/v1/auth/login")
                .then().log().all()
                .statusCode(401)
                .contentType(containsString("application/problem+json"))
                .body("title", equalTo("Invalid token"))
                .body("detail", equalTo("unsupported provider: facebook"));
    }

    @Test
    void ATC_login_malformedToken_returns401ProblemJson() {
        given().log().all()
                .baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body(loginBody("kakao", "wrong-format"))
                .when()
                .post("/api/v1/auth/login")
                .then().log().all()
                .statusCode(401)
                .contentType(containsString("application/problem+json"))
                .body("title", equalTo("Invalid token"))
                .body("detail", equalTo("malformed token for provider: kakao"));
    }

    @Test
    void ATC_login_emptySeed_returns401ProblemJson() {
        given().log().all()
                .baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body(loginBody("naver", "valid-naver-"))
                .when()
                .post("/api/v1/auth/login")
                .then().log().all()
                .statusCode(401)
                .contentType(containsString("application/problem+json"))
                .body("title", equalTo("Invalid token"))
                .body("detail", equalTo("empty seed"));
    }

    // ------------------------------------------------------------------
    // VTC — RED 파라미터(provider, providerToken) 표준 rule: NULL, EMPTY, WHITE_SPACE
    // 둘 다 in-memory Set.contains/startsWith 비교로만 쓰이며 실제 SQL WHERE 절에는
    // 쓰이지 않으므로 SPECIAL_CHAR 는 적용하지 않는다(rule 은 DB_WHERE 조건에 한정).
    // @Size 제약이 없어 LENGTH_EXCEEDED/LENGTH_SHRUNK 도 해당 없음.
    // ------------------------------------------------------------------

    @Test
    void VTC_provider_NULL() {
        given().baseUri(BASE_URL).contentType(ContentType.JSON)
                .body("{\"providerToken\":\"valid-kakao-x\"}")
                .when().post("/api/v1/auth/login")
                .then()
                .statusCode(400)
                .contentType(containsString("application/problem+json"));
    }

    @Test
    void VTC_provider_EMPTY() {
        given().baseUri(BASE_URL).contentType(ContentType.JSON)
                .body(loginBody("", "valid-kakao-x"))
                .when().post("/api/v1/auth/login")
                .then()
                .statusCode(400)
                .contentType(containsString("application/problem+json"));
    }

    @Test
    void VTC_provider_WHITE_SPACE() {
        given().baseUri(BASE_URL).contentType(ContentType.JSON)
                .body(loginBody("   ", "valid-kakao-x"))
                .when().post("/api/v1/auth/login")
                .then()
                .statusCode(400)
                .contentType(containsString("application/problem+json"));
    }

    @Test
    void VTC_providerToken_NULL() {
        given().baseUri(BASE_URL).contentType(ContentType.JSON)
                .body("{\"provider\":\"kakao\"}")
                .when().post("/api/v1/auth/login")
                .then()
                .statusCode(400)
                .contentType(containsString("application/problem+json"));
    }

    @Test
    void VTC_providerToken_EMPTY() {
        given().baseUri(BASE_URL).contentType(ContentType.JSON)
                .body(loginBody("kakao", ""))
                .when().post("/api/v1/auth/login")
                .then()
                .statusCode(400)
                .contentType(containsString("application/problem+json"));
    }

    @Test
    void VTC_providerToken_WHITE_SPACE() {
        given().baseUri(BASE_URL).contentType(ContentType.JSON)
                .body(loginBody("kakao", "   "))
                .when().post("/api/v1/auth/login")
                .then()
                .statusCode(400)
                .contentType(containsString("application/problem+json"));
    }
}

