package com.tainted.authuser.blackbox;

import io.lettuce.core.RedisClient;
import io.lettuce.core.api.StatefulRedisConnection;
import io.lettuce.core.api.sync.RedisCommands;
import io.restassured.http.ContentType;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.Statement;
import java.util.Map;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.*;

/**
 * Black-Box API Integration Test
 *
 * @target-controller InternalAuthController (src/main/java/com/tainted/authuser/web/InternalAuthController.java)
 * @target-api POST /internal/auth/verify
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class AuthVerifyBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8081");

    private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:3306/authuser");
    private static final String DB_USER = System.getProperty("test.db.user", "root");
    private static final String DB_PASSWORD = System.getProperty("test.db.password", "rootpw");

    private static final String REDIS_HOST = System.getProperty("test.redis.host", "localhost");
    private static final int REDIS_PORT = Integer.getInteger("test.redis.port", 6379);

    private static final String REDIS_TOKEN_PREFIX = "auth:token:";

    private static RedisClient redisClient;

    @BeforeAll
    static void startClients() {
        redisClient = RedisClient.create("redis://" + REDIS_HOST + ":" + REDIS_PORT);
    }

    @AfterAll
    static void stopClients() {
        redisClient.shutdown();
    }

    private static Connection getDbConnection() throws Exception {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
        try (Connection conn = getDbConnection();
             InputStream is = AuthVerifyBlackBoxTest.class
                     .getClassLoader().getResourceAsStream(resourcePath);
             Statement stmt = conn.createStatement()) {
            String sql = new String(is.readAllBytes(), StandardCharsets.UTF_8);
            for (var entry : params.entrySet()) {
                sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
            }
            for (String line : sql.split("\n")) {
                String trimmed = line.trim();
                if (trimmed.startsWith("--") || trimmed.isEmpty()) continue;
                if (trimmed.endsWith(";")) trimmed = trimmed.substring(0, trimmed.length() - 1);
                if (!trimmed.isEmpty()) stmt.execute(trimmed);
            }
        } catch (Exception e) {
            throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
        }
    }

    private String testId(TestInfo info) {
        return String.format("T%09d",
                Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000);
    }

    private String verifyBody(String token) {
        return "{\"token\":\"" + token + "\"}";
    }

    // ------------------------------------------------------------------
    // NTC — Happy Path (verify() never throws; it always returns 200)
    // ------------------------------------------------------------------

    @Test
    void NTC_verify_activeToken_returns200WithUserData(TestInfo info) {
        String userId = testId(info);
        String externalId = "kakao:" + userId;
        String token = "verify-active-" + userId;

        executeSqlTemplate("sql/internal-auth-verify-setup.sql", Map.of(
                "USER_ID", userId, "SOCIAL_PROVIDER", "kakao", "EXTERNAL_ID", externalId));

        try (StatefulRedisConnection<String, String> conn = redisClient.connect()) {
            RedisCommands<String, String> commands = conn.sync();
            commands.setex(REDIS_TOKEN_PREFIX + token, 60, userId);

            try {
                given().log().all()
                        .baseUri(BASE_URL)
                        .contentType(ContentType.JSON)
                        .body(verifyBody(token))
                        .when()
                        .post("/internal/auth/verify")
                        .then().log().all()
                        .statusCode(200)
                        .body("active", equalTo(true))
                        .body("userId", equalTo(userId))
                        .body("socialProvider", equalTo("kakao"));
            } finally {
                commands.del(REDIS_TOKEN_PREFIX + token);
            }
        } finally {
            executeSqlTemplate("sql/internal-auth-verify-teardown.sql", Map.of("USER_ID", userId));
        }
    }

    @Test
    void NTC_verify_unknownToken_returns200WithFalseAndNulls(TestInfo info) {
        String token = "verify-unknown-" + testId(info);

        given().log().all()
                .baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body(verifyBody(token))
                .when()
                .post("/internal/auth/verify")
                .then().log().all()
                .statusCode(200)
                .body("active", equalTo(false))
                .body("userId", nullValue())
                .body("socialProvider", nullValue());
    }

    @Test
    void NTC_verify_tokenValidButUserDeleted_returns200WithFalse(TestInfo info) {
        // Redis 는 여전히 token->userId 매핑을 갖고 있지만, user_account 에는 해당
        // id 가 존재하지 않는 경우 (flatMap(repository::findById) 가 empty 로 단락).
        String orphanUserId = testId(info);
        String token = "verify-orphan-" + orphanUserId;

        try (StatefulRedisConnection<String, String> conn = redisClient.connect()) {
            RedisCommands<String, String> commands = conn.sync();
            commands.setex(REDIS_TOKEN_PREFIX + token, 60, orphanUserId);

            try {
                given().log().all()
                        .baseUri(BASE_URL)
                        .contentType(ContentType.JSON)
                        .body(verifyBody(token))
                        .when()
                        .post("/internal/auth/verify")
                        .then().log().all()
                        .statusCode(200)
                        .body("active", equalTo(false))
                        .body("userId", nullValue())
                        .body("socialProvider", nullValue());
            } finally {
                commands.del(REDIS_TOKEN_PREFIX + token);
            }
        }
    }

    // ------------------------------------------------------------------
    // ATC — API 레벨 변조 (verify() 자체는 예외를 던지지 않으므로 유일하게
    // 검증 가능한 실제 프레임워크 동작은 잘못된 HTTP 메서드 사용).
    // ------------------------------------------------------------------

    @Test
    void ATC_verify_wrongMethodReturns405() {
        given().baseUri(BASE_URL).log().all()
                .when().get("/internal/auth/verify")
                .then().log().all()
                .statusCode(405);
    }

    // ------------------------------------------------------------------
    // VTC — RED 파라미터(token) 표준 rule: NULL, EMPTY, WHITE_SPACE.
    // token 은 in-memory null/blank 체크와 Redis GET 키로만 쓰이고 SQL WHERE
    // 절에는 쓰이지 않으므로 SPECIAL_CHAR 는 적용하지 않는다.
    // ------------------------------------------------------------------

    @Test
    void VTC_token_NULL() {
        given().baseUri(BASE_URL).contentType(ContentType.JSON)
                .body("{}")
                .when().post("/internal/auth/verify")
                .then()
                .statusCode(400)
                .contentType(containsString("application/problem+json"));
    }

    @Test
    void VTC_token_EMPTY() {
        given().baseUri(BASE_URL).contentType(ContentType.JSON)
                .body(verifyBody(""))
                .when().post("/internal/auth/verify")
                .then()
                .statusCode(400)
                .contentType(containsString("application/problem+json"));
    }

    @Test
    void VTC_token_WHITE_SPACE() {
        given().baseUri(BASE_URL).contentType(ContentType.JSON)
                .body(verifyBody("   "))
                .when().post("/internal/auth/verify")
                .then()
                .statusCode(400)
                .contentType(containsString("application/problem+json"));
    }
}

