        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
        try (Connection conn = getDbConnection();
             InputStream is = UsersGetBlackBoxTest.class
                     .getClassLoader().getResourceAsStream(resourcePath);
             Statement stmt = conn.createStatement()) {
            String sql = new String(is.readAllBytes(), StandardCharsets.UTF_8);
            for (var entry : params.entrySet()) {
                sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
            }
            for (String line : sql.split("\n")) {
                String trimmed = line.trim();
                if (trimmed.startsWith("--") || trimmed.isEmpty()) continue;
                if (trimmed.endsWith(";")) trimmed = trimmed.substring(0, trimmed.length() - 1);
                if (!trimmed.isEmpty()) stmt.execute(trimmed);
            }
        } catch (Exception e) {
            throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
        }
    }

    private String testId(TestInfo info) {
        return String.format("T%09d",
                Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000);
    }

    /** insert 후 실제 저장된 created_at 을 JDBC 로 다시 읽어와 응답과 대조할 authoritative 값을 얻는다. */
    private Instant insertAndReadBackCreatedAt(String id, String provider, String externalId, String createdAtLiteral) {
        executeSqlTemplate("sql/internal-users-get-setup.sql", Map.of(
                "USER_ID", id, "SOCIAL_PROVIDER", provider, "EXTERNAL_ID", externalId, "CREATED_AT", createdAtLiteral));
        try (Connection conn = getDbConnection();
             PreparedStatement ps = conn.prepareStatement("SELECT created_at FROM user_account WHERE id = ?")) {
            ps.setString(1, id);
            try (ResultSet rs = ps.executeQuery()) {
                assertTrue(rs.next());
                return rs.getTimestamp("created_at").toInstant();
            }
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    // ------------------------------------------------------------------
    // NTC — Happy Path
    // ------------------------------------------------------------------

    @Test
    void NTC_getUser_found_returns200WithUserData(TestInfo info) {
        String id = testId(info);
        String externalId = "kakao:" + id;
        Instant createdAt = insertAndReadBackCreatedAt(id, "kakao", externalId, "2026-06-15 12:34:56");

        try {
            given().log().all()
                    .baseUri(BASE_URL)
                    .pathParam("id", id)
                    .when()
                    .get("/internal/users/{id}")
                    .then().log().all()
                    .statusCode(200)
                    .body("id", equalTo(id))
                    .body("socialProvider", equalTo("kakao"))
                    .body("createdAt", equalTo(createdAt.toString()));
        } finally {
            executeSqlTemplate("sql/internal-users-get-teardown.sql", Map.of("USER_ID", id));
        }
    }

    @Test
    void NTC_getUser_differentProviderCombination_returns200(TestInfo info) {
        String id = "g-" + testId(info);
        String externalId = "google:" + id;
        Instant createdAt = insertAndReadBackCreatedAt(id, "google", externalId, "2025-12-25 00:00:00");

        try {
            given().log().all()
                    .baseUri(BASE_URL)
                    .pathParam("id", id)
                    .when()
                    .get("/internal/users/{id}")
                    .then().log().all()
                    .statusCode(200)
                    .body("id", equalTo(id))
                    .body("socialProvider", equalTo("google"))
                    .body("createdAt", equalTo(createdAt.toString()));
        } finally {
            executeSqlTemplate("sql/internal-users-get-teardown.sql", Map.of("USER_ID", id));
        }
    }

    @Test
