        // user_account.id 는 VARCHAR(64) — 정확히 경계값(64자)에서도 정상 동작해야 한다.
        String base = testId(info); // 10 chars ("T" + 9 digits)
        String id = (base + "x".repeat(64 - base.length()));
        assertTrue(id.length() == 64);
        String externalId = "naver:" + base;
        Instant createdAt = insertAndReadBackCreatedAt(id, "naver", externalId, "2026-03-01 09:00:00");

        try {
            given().log().all()
                    .baseUri(BASE_URL)
                    .pathParam("id", id)
                    .when()
                    .get("/internal/users/{id}")
                    .then().log().all()
                    .statusCode(200)
                    .body("id", equalTo(id))
