        String id = "missing-" + testId(info);

        given().log().all()
                .baseUri(BASE_URL)
                .pathParam("id", id)
                .when()
                .get("/internal/users/{id}")
                .then().log().all()
                .statusCode(404)
                .contentType(containsString("application/problem+json"))
                .body("title", equalTo("User not found"))
                .body("detail", equalTo("user not found: " + id));
    }

    // ------------------------------------------------------------------
    // VTC — RED 파라미터(id) 표준 rule: id 는 findById() 의 SQL WHERE 절에 직접
    // 쓰이므로(DB_WHERE) NULL/EMPTY/WHITE_SPACE/SPECIAL_CHAR/LENGTH_EXCEEDED/
    // LENGTH_SHRUNK 전체 rule 이 적용 대상이다 (DDL: user_account.id VARCHAR(64)).
    // ------------------------------------------------------------------

    @Test
    void VTC_id_NULL() {
        // path variable 자체가 없는 요청 — "/internal/users/{id}" 매핑에 매치되지 않음.
        given().baseUri(BASE_URL).log().all()
                .when().get("/internal/users")
                .then().log().all()
                .statusCode(404);
    }

    @Test
    void VTC_id_EMPTY() {
        // trailing slash, 빈 path segment — 매핑에 매치되지 않음.
        given().baseUri(BASE_URL).log().all()
                .when().get("/internal/users/")
                .then().log().all()
                .statusCode(404);
    }

    @Test
    void VTC_id_WHITE_SPACE() {
        String id = "   ";
        given().baseUri(BASE_URL).log().all()
                .pathParam("id", id)
                .when().get("/internal/users/{id}")
                .then().log().all()
                .statusCode(404)
                .contentType(containsString("application/problem+json"))
                .body("detail", equalTo("user not found: " + id));
    }

    @Test
    void VTC_id_SPECIAL_CHAR() {
        String id = "'; DROP TABLE --";
        given().baseUri(BASE_URL).log().all()
                .pathParam("id", id)
                .when().get("/internal/users/{id}")
                .then().log().all()
                .statusCode(404)
                .contentType(containsString("application/problem+json"))
                .body("detail", equalTo("user not found: " + id));
    }

    @Test
    void VTC_id_LENGTH_EXCEEDED(TestInfo info) {
        // DDL: user_account.id VARCHAR(64) — 65자는 컬럼 길이를 초과하므로 어떤 행과도
        // 매치될 수 없다 (INSERT 라면 truncation 에러겠지만, SELECT ... WHERE 비교는
        // 에러 없이 단순히 미매치로 처리됨).
        String id = "x".repeat(65);
        given().baseUri(BASE_URL).log().all()
                .pathParam("id", id)
                .when().get("/internal/users/{id}")
                .then().log().all()
                .statusCode(404)
                .contentType(containsString("application/problem+json"))
                .body("detail", equalTo("user not found: " + id));
    }

    @Test
    void VTC_id_LENGTH_SHRUNK() {
        String id = "x";
        given().baseUri(BASE_URL).log().all()
                .pathParam("id", id)
                .when().get("/internal/users/{id}")
                .then().log().all()
                .statusCode(404)
                .contentType(containsString("application/problem+json"))
                .body("detail", equalTo("user not found: " + id));
    }
}

